func:
if (msg.payload > 50) {
    msg.payload = "Alarma mayor a 50";
} else {
    msg = null;
}
return msg;

rules.to:
(
  $co2 := $flowContext("co2");
  $pm := $flowContext("pm25");
  $alarmaCO2 := $exists($co2) and $co2 > 1000;
  $alarmaPM25 := $exists($pm) and $pm > 55;
  {
    "sistema": {
      "nombre": "Monitoreo Ambiental Inteligente",
      "ubicacion": "Laboratorio IoT",
      "estado": {
        "ventilacion": ($alarmaCO2 or $alarmaPM25) ? "encendida" : "apagada",
        "alarmaCO2": $alarmaCO2,
        "alarmaPM25": $alarmaPM25
      }
    }
  }
)
